args.streamContent:
@font-face {
  font-family: "Bodoni Moda";
  src: url("fonts/bodoni-moda.woff2") format("woff2");
  font-weight: 400 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Bodoni Moda";
  src: url("fonts/bodoni-moda-italic.woff2") format("woff2");
  font-weight: 400 900;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "Outfit";
  src: url("fonts/outfit.woff2") format("woff2");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #08161c;
  --ink-2: #12303a;
  --paper: #f3ecdf;
  --coral: #ef7a66;
  --coral-ink: #7d2e28;
  --gold: #f0b429;
  --head: 3.25rem;
  --serif: "Bodoni Moda", Didot, "Bodoni MT", "Times New Roman", serif;
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  overflow-x: clip;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-weight: 400;
  font-size: 1.05rem;
  line-height: 1.5;
  text-rendering: optimizeLegibility;
}

img {
  max-width: 100%;
  display: block;
  -webkit-user-drag: none;
  user-select: none;
}

button,
input {
  font: inherit;
  color: inherit;
}

h1,
h2,
p {
  margin: 0;
}

::selection {
  background: var(--coral);
  color: var(--ink);
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.sr,
.defs {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 40;
  background: var(--paper);
  color: var(--ink);
  padding: 0.45rem 0.7rem;
  text-decoration: none;
}

.skip:focus {
  top: 0.6rem;
}

.running-head {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 20;
  height: var(--head);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0 4vw;
  background: var(--ink);
  border-bottom: 1px solid rgba(240, 180, 41, 0.42);
}

.brand {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--paper);
  text-decoration: none;
  letter-spacing: 0.01em;
}

.running-head nav {
  display: flex;
  gap: 1.2rem;
}

.running-head nav a {
  color: var(--paper);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
}

.running-head a:hover,
.running-head nav a.is-current {
  color: var(--gold);
}

.hero {
  container-type: inline-size;
  min-height: 100svh;
  padding: calc(var(--head) + 1.15rem) 1.15rem 2.4rem;
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-optical-sizing: auto;
  font-size: clamp(4.5rem, 23cqi, 7.4rem);
  line-height: 0.84;
  letter-spacing: -0.03em;
  width: min-content;
  max-width: 100%;
  color: var(--paper);
  animation: rise 0.9s 0.05s both;
}

.hero-copy {
  max-width: 34rem;
  animation: rise 0.9s 0.16s both;
}

.dek {
  font-size: 1.2rem;
  line-height: 1.35;
}

.lede {
  margin-top: 0.7rem;
  max-width: 38ch;
  color: rgba(243, 236, 223, 0.86);
}

.hero-stage {
  animation: rise 1s 0.22s both;
}

.arch {
  cursor: ew-resize;
  touch-action: pan-y;
  --px: 0;
  --py: 0;
}

.arch-stack {
  position: relative;
  height: min(58svh, 540px);
  min-height: 300px;
  transform-origin: 50% 72%;
  animation: unseal 1.05s cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.arch-gold,
.arch-layers,
.door-gold,
.door {
  -webkit-clip-path: url("#arch");
  clip-path: url("#arch");
}

.arch-gold,
.arch-layers {
  position: absolute;
  inset: 0;
}

.arch-gold {
  inset: -7px;
  background: var(--gold);
}

.arch-layers {
  background: var(--ink-2);
  overflow: hidden;
}

.composite,
.solo,
.base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.base,
.solo,
.shard img {
  object-fit: cover;
}

.base {
  object-position: 50% 46%;
  transform: translate3d(calc(var(--px) * -12px), calc(var(--py) * -8px), 0) scale(1.06);
}

.solo {
  opacity: 0;
  object-position: 50% 45%;
  transform: translate3d(calc(var(--px) * -14px), calc(var(--py) * -10px), 0) scale(1.07);
}

.solo:nth-child(2) {
  object-position: 50% 48%;
}

.solo:nth-child(3) {
  object-position: 34% 40%;
}

.solo:nth-child(4) {
  object-position: 62% 52%;
}

.solo:nth-child(5) {
  object-position: 50% 42%;
}

.composite {
  opacity: 1;
}

.arch.is-solo .composite {
  opacity: 0;
}

.arch.is-solo .solo.is-on {
  opacity: 1;
}

.base,
.solo,
.composite,
.shard img {
  transition: opacity 0.45s ease, transform 0.4s ease-out;
}

.shard {
  position: absolute;
  overflow: hidden;
  z-index: 2;
}

.shard img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.shard-door {
  left: 7%;
  top: 14%;
  bottom: 0;
  width: 19%;
  box-shadow: inset 1px 0 0 var(--gold), inset -1px 0 0 var(--gold);
}

.shard-door img {
  object-position: 50% 38%;
  transform: translate3d(calc(var(--px) * -18px), calc(var(--py) * -10px), 0) scale(1.15);
}

.shard-moon {
  width: 40%;
  aspect-ratio: 1;
  right: 7%;
  top: 8%;
  border-radius: 50%;
  box-shadow: 0 0 0 1.5px var(--gold);
  z-index: 3;
}

.shard-moon img {
  object-position: 58% 42%;
  transform: translate3d(calc(var(--px) * -22px), calc(var(--py) * -16px), 0) scale(1.18);
}

.shard-tear {
  left: 22%;
  right: 0;
  bottom: 0;
  height: 40%;
  clip-path: polygon(0 32%, 100% 6%, 100% 100%, 0 100%);
  z-index: 4;
}

.shard-tear img {
  object-position: 30% 22%;
  transform: translate3d(calc(var(--px) * -16px), calc(var(--py) * -12px), 0) scale(1.12);
}

.mark {
  position: absolute;
  width: 13px;
  height: 13px;
  z-index: 5;
  pointer-events: none;
}

.mark.tl {
  top: -11px;
  left: -11px;
  border-top: 1px solid var(--gold);
  border-left: 1px solid var(--gold);
}

.mark.tr {
  top: -11px;
  right: -11px;
  border-top: 1px solid var(--gold);
  border-right: 1px solid var(--gold);
}

.mark.bl {
  bottom: -11px;
  left: -11px;
  border-bottom: 1px solid var(--gold);
  border-left: 1px solid var(--gold);
}

.mark.br {
  bottom: -11px;
  right: -11px;
  border-bottom: 1px solid var(--gold);
  border-right: 1px solid var(--gold);
}

.arch-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.9rem 1.2rem;
  margin-top: 0.95rem;
}

.arch-kicker {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(1.7rem, 3vw, 2.35rem);
  line-height: 0.95;
  letter-spacing: -0.03em;
}

.arch-line {
  margin-top: 0.4rem;
  max-width: 38ch;
  color: rgba(243, 236, 223, 0.88);
}

.spines {
  display: flex;
  gap: 0.45rem;
}

.spines button {
  width: 3.15rem;
  height: 4.15rem;
  padding: 0;
  border: 1px solid transparent;
  background: var(--ink-2);
  cursor: pointer;
  overflow: hidden;
}

.spines button img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.spines button:nth-child(1) img {
  object-position: 50% 50%;
}

.spines button:nth-child(2) img {
  object-position: 32% 36%;
}

.spines button:nth-child(3) img {
  object-position: 60% 48%;
}

.spines button:nth-child(4) img {
  object-position: 50% 40%;
}

.spines button[aria-checked="true"] {
  border-color: var(--gold);
}

.spines button:hover {
  border-color: rgba(240, 180, 41, 0.7);
}

.reunite {
  margin-top: 0.75rem;
  padding: 0 0 0.12rem;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--coral);
  color: var(--coral);
  cursor: pointer;
}

.reunite:hover {
  color: var(--paper);
  border-bottom-color: var(--paper);
}

.room {
  position: relative;
  scroll-margin-top: calc(var(--head) + 0.4rem);
}

.plate {
  background: var(--paper);
  color: var(--ink);
  padding: 1.15rem 1.25rem 1.3rem;
  max-width: 26rem;
  box-shadow: 7px 7px 0 var(--gold);
  position: relative;
  z-index: 2;
}

.plate-no {
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  color: var(--coral-ink);
}

.plate h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2.15rem, 4.4vw, 3.35rem);
  line-height: 0.94;
  letter-spacing: -0.03em;
  margin: 0.25rem 0 0.7rem;
}

.plate p:last-child {
  font-size: 1.02rem;
  line-height: 1.45;
}

.room-library .plate {
  background: var(--coral);
  box-shadow: 7px 7px 0 var(--ink);
}

.room-library .plate-no {
  color: var(--ink);
}

.room-atelier {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1.25rem;
  padding: 4.5rem 1.15rem 3.5rem;
}

.oval {
  margin: 0;
  width: min(92vw, 980px);
  aspect-ratio: 16 / 10.4;
  border-radius: 50%;
  overflow: hidden;
  align-self: center;
  outline: 1px solid var(--gold);
  outline-offset: 10px;
}

.oval img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 58%;
}

.room-library {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  padding: 1.5rem 1.15rem 3.5rem;
}

.slash {
  margin: 0;
  height: 52svh;
  min-height: 260px;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 86%);
  overflow: hidden;
}

.slash img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 36% 42%;
}

.room-valley {
  display: flex;
  flex-direction: column;
  gap: 1.6rem;
  padding: 1rem 1.15rem 4rem;
  overflow: hidden;
}

.oculus {
  margin: 0 auto;
  width: min(78vw, 440px);
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 0 8px var(--gold);
  flex: 0 0 auto;
}

.oculus img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 58% 58%;
}

.room-night {
  min-height: 100svh;
}

.night-img {
  width: 100%;
  height: 72svh;
  object-fit: cover;
  object-position: 50% 42%;
}

.room-night .plate {
  margin: -2.6rem 1.15rem 2.5rem;
}

.ledger {
  scroll-margin-top: calc(var(--head) + 0.4rem);
  display: flex;
  flex-direction: column;
  gap: 1.6rem;
  padding: 3.5rem 1.15rem 3rem;
}

.ledger h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2.6rem, 8vw, 4.6rem);
  line-height: 0.92;
  letter-spacing: -0.03em;
  max-width: 10ch;
}

.ledger .lede {
  margin-top: 0.9rem;
}

.door-wrap {
  position: relative;
  width: min(68vw, 260px);
  height: 46svh;
  min-height: 280px;
  align-self: flex-end;
  order: -1;
}

.door-gold,
.door {
  position: absolute;
  inset: 0;
}

.door-gold {
  inset: -6px;
  background: var(--gold);
}

.door {
  margin: 0;
  overflow: hidden;
  background: var(--ink-2);
}

.door img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 58%;
}

form {
  margin-top: 1.5rem;
}

label {
  display: block;
  margin-bottom: 0.35rem;
  font-size: 0.92rem;
  font-weight: 500;
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.8rem 1.2rem;
}

input {
  width: min(100%, 22rem);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--gold);
  border-radius: 0;
  padding: 0.65rem 0;
  font-size: 1.05rem;
}

input:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 4px;
}

form button {
  background: none;
  border: 0;
  border-bottom: 1px solid var(--coral);
  color: var(--coral);
  padding: 0.35rem 0 0.12rem;
  cursor: pointer;
}

form button:hover {
  color: var(--paper);
  border-bottom-color: var(--paper);
}

.form-error {
  margin-top: 0.7rem;
  color: #ffc2b6;
}

.success {
  margin-top: 1.4rem;
}

.success-line {
  font-family: var(--serif);
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  line-height: 1.05;
  letter-spacing: -0.03em;
}

#guest-name {
  overflow-wrap: anywhere;
}

.colophon {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.6rem 1.5rem;
  padding: 1.4rem 1.15rem 1.8rem;
  border-top: 1px solid rgba(240, 180, 41, 0.35);
  color: rgba(243, 236, 223, 0.78);
  font-size: 0.95rem;
}

.colophon a {
  color: var(--coral);
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes unseal {
  from {
    opacity: 0;
    transform: scaleY(0.045);
  }
  to {
