  const ids = ["atelier", "library", "valley", "night", "ledger"];
  const rows = ids.map((id) => {
    const el = document.getElementById(id);
    const r = el.getBoundingClientRect();
    const s = getComputedStyle(el);
    return {
      id,
      top: Math.round(el.offsetTop),
      height: Math.round(el.offsetHeight),
      overflow: s.overflow,
      scrollW: el.scrollWidth,
      clientW: el.clientWidth,
    };
  });
  return {
    doc: document.documentElement.scrollWidth,
    inner: innerWidth,
    rows,
  };
});

await page.locator(".spines button").nth(2).click();
await page.waitForTimeout(500);
const after = await page.evaluate(() => ({
  kicker: document.querySelector("#arch-kicker").textContent,
  line: document.querySelector("#arch-line").textContent,
  solo: document.querySelector("#arch").classList.contains("is-solo"),
  checked: [...document.querySelectorAll(".spines button")].map((b) => b.getAttribute("aria-checked")),
  reunite: document.querySelector(".reunite").hidden,
}));
