await page.locator(".reunite").click();
await page.waitForTimeout(400);
const back = await page.evaluate(() => ({
  kicker: document.querySelector("#arch-kicker").textContent,
  solo: document.querySelector("#arch").classList.contains("is-solo"),
  reuniteHidden: document.querySelector(".reunite").hidden,
}));

