    flex-wrap: wrap;
    align-items: flex-end;
    padding: 0.7rem 1rem 0.55rem;
    row-gap: 0.35rem;
  }

  .running-head nav {
    width: 100%;
    justify-content: space-between;
    gap: 0.4rem;
  }

