    bottom: 8vh;
    margin: 0;
  }

  .room-library {
    display: grid;
    grid-template-columns: minmax(17rem, 30rem) minmax(0, 1fr);
    align-items: center;
    gap: 0;
    min-height: 100svh;
    padding: 0 0 0 5vw;
  }

  .slash {
    height: 100svh;
    min-height: 100svh;
    margin-left: -6vw;
    clip-path: polygon(16% 0, 100% 0, 100% 100%, 0 100%);
