dev-browser <<'EOF'
const page = await browser.getPage("elysian");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));
page.on("console", (msg) => { if (msg.type() === "error") errors.push(msg.text()); });

await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("http://127.0.0.1:9477/", { waitUntil: "networkidle" });
await page.waitForTimeout(700);

const arch = page.locator("div#arch");
const box = await arch.boundingBox();
await page.mouse.move(box.x + 30, box.y + box.height * 0.55);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.78, box.y + box.height * 0.55, { steps: 10 });
await page.mouse.up();
await page.waitForTimeout(500);
const dragged = await page.evaluate(() => ({
  kicker: document.querySelector("#arch-kicker").textContent,
  line: document.querySelector("#arch-line").textContent,
  solo: document.querySelector("div#arch").classList.contains("is-solo"),
  checked: [...document.querySelectorAll(".spines button")].map((b) => b.getAttribute("aria-checked")),
}));
const dragShot = await saveScreenshot(await page.screenshot(), "desktop-drag.png");

await page.keyboard.press("Home");
await page.locator("div#arch").focus();
await page.keyboard.press("ArrowRight");
await page.waitForTimeout(300);
const keyed = await page.evaluate(() => document.querySelector("#arch-kicker").textContent);
await page.locator(".reunite").click();
await page.waitForTimeout(300);

await page.locator("#guest").fill("Isolde Vesper");
await page.locator("#key-form button").click();
await page.waitForTimeout(250);
await page.locator("#ledger").scrollIntoViewIfNeeded();
await page.waitForTimeout(300);
const success = await page.evaluate(() => document.querySelector("#success").innerText);
const ledgerShot = await saveScreenshot(await page.screenshot(), "desktop-success.png");

await page.setViewportSize({ width: 390, height: 844 });
await page.goto("http://127.0.0.1:9477/", { waitUntil: "networkidle" });
await page.waitForTimeout(600);
const mobile = await page.evaluate(() => {
  const h = document.querySelector("h1");
  const r = h.getBoundingClientRect();
  return {
    scrollWidth: document.documentElement.scrollWidth,
    innerWidth: innerWidth,
    h1: { w: r.width, h: r.height, top: r.top, left: r.left, size: getComputedStyle(h).fontSize, text: h.textContent },
    headH: document.querySelector(".running-head").getBoundingClientRect().height,
  };
});
const mHero = await saveScreenshot(await page.screenshot(), "mobile-hero.png");
await page.evaluate(() => window.scrollTo(0, document.getElementById("atelier").offsetTop - 90));
await page.waitForTimeout(400);
const mAtelier = await saveScreenshot(await page.screenshot(), "mobile-atelier.png");
await page.evaluate(() => window.scrollTo(0, document.getElementById("library").offsetTop - 90));
await page.waitForTimeout(400);
const mLib = await saveScreenshot(await page.screenshot(), "mobile-library.png");
await page.evaluate(() => window.scrollTo(0, document.getElementById("valley").offsetTop - 90));
await page.waitForTimeout(400);
const mVal = await saveScreenshot(await page.screenshot(), "mobile-valley.png");
await page.evaluate(() => window.scrollTo(0, document.getElementById("night").offsetTop - 80));
await page.waitForTimeout(400);
const mNight = await saveScreenshot(await page.screenshot(), "mobile-night.png");
await page.evaluate(() => window.scrollTo(0, document.getElementById("ledger").offsetTop - 80));
await page.waitForTimeout(400);
const mLed = await saveScreenshot(await page.screenshot(), "mobile-ledger.png");

console.log(JSON.stringify({ errors, dragged, keyed, success, dragShot, ledgerShot, mobile, mHero, mAtelier, mLib, mVal, mNight, mLed }, null, 2));
EOF

