  width: 13px;
  height: 13px;
  z-index: 5;
  pointer-events: none;
}

.mark.tl {
  top: -11px;
  left: -11px;
  border-top: 1px solid var(--gold);
  border-left: 1px solid var(--gold);
}

.mark.tr {
  top: -11px;
  right: -11px;
  border-top: 1px solid var(--gold);
  border-right: 1px solid var(--gold);
}

.mark.bl {
  bottom: -11px;
  left: -11px;
  border-bottom: 1px solid var(--gold);
  border-left: 1px solid var(--gold);
}

.mark.br {
  bottom: -11px;
  right: -11px;
  border-bottom: 1px solid var(--gold);
  border-right: 1px solid var(--gold);
