  justify-content: center;
  gap: 1.25rem;
  padding: 4.5rem 1.15rem 3.5rem;
}

.oval {
  margin: 0;
  width: min(92vw, 980px);
  aspect-ratio: 16 / 10.4;
  border-radius: 50%;
  overflow: hidden;
  align-self: center;
  outline: 1px solid var(--gold);
  outline-offset: 10px;
}

.oval img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 58%;
}

.room-library {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  padding: 1.5rem 1.15rem 3.5rem;
  overflow: hidden;
}

.slash {
  margin: 0;
  height: 52svh;
  min-height: 260px;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 86%);
  overflow: hidden;
}

.slash img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 36% 42%;
}

.room-valley {
  display: flex;
  flex-direction: column;
  gap: 1.6rem;
  padding: 1rem 1.15rem 4rem;
  overflow: hidden;
}

.oculus {
  margin: 0 auto;
  width: min(78vw, 440px);
  aspect-ratio: 1;
  border-radius: 50%;
