  flex-direction: column;
  gap: 1.6rem;
  padding: 3.5rem 1.15rem 3rem;
}

.ledger h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2.6rem, 8vw, 4.6rem);
  line-height: 0.92;
  letter-spacing: -0.03em;
  max-width: 10ch;
}

.ledger .lede {
  margin-top: 0.9rem;
}

.door-wrap {
