  width: min(68vw, 260px);
  height: 46svh;
  min-height: 280px;
  align-self: flex-end;
  order: -1;
}

.door-gold,
.door {
  position: absolute;
  inset: 0;
}

.door-gold {
  inset: -6px;
  background: var(--gold);
}

.door {
  margin: 0;
  overflow: hidden;
  background: var(--ink-2);
}

.door img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 58%;
}

form {
  margin-top: 1.5rem;
}

label {
  display: block;
  margin-bottom: 0.35rem;
  font-size: 0.92rem;
  font-weight: 500;
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.85rem 1.4rem;
  max-width: 38rem;
}

input {
  flex: 1 1 14rem;
  width: auto;
  min-width: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--gold);
  border-radius: 0;
  padding: 0.65rem 0;
  font-size: 1.05rem;
}

input:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 4px;
}

form button {
  background: none;
  border: 0;
  border-bottom: 1px solid var(--coral);
  color: var(--coral);
  padding: 0.35rem 0 0.12rem;
  cursor: pointer;
}

form button:hover {
  color: var(--paper);
  border-bottom-color: var(--paper);
}

.form-error {
  margin-top: 0.7rem;
  color: #ffc2b6;
}

.success {
  margin-top: 1.4rem;
}

.success-line {
  font-family: var(--serif);
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  line-height: 1.05;
  letter-spacing: -0.03em;
}

