  color: rgba(243, 236, 223, 0.78);
  font-size: 0.95rem;
}

.colophon a {
  color: var(--coral);
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes unseal {
  from {
    opacity: 0;
    transform: scaleY(0.045);
  }
  to {
    opacity: 1;
    transform: scaleY(1);
  }
}

.js .plate {
  opacity: 0;
  transform: translateY(18px) rotate(var(--tilt, 0deg));
  transition: opacity 0.7s ease, transform 0.75s cubic-bezier(0.16, 0.84, 0.28, 1);
}

.js .room.is-in .plate {
  opacity: 1;
  transform: translateY(0) rotate(var(--tilt, 0deg));
}

@media (max-width: 680px) {
  :root {
    --head: 5.35rem;
  }

  .running-head {
    height: auto;
    flex-wrap: wrap;
    align-items: flex-end;
    padding: 0.7rem 1rem 0.55rem;
    row-gap: 0.35rem;
  }

  .running-head nav {
    width: 100%;
    justify-content: space-between;
    gap: 0.4rem;
  }

  .running-head nav a {
    font-size: 0.86rem;
  }
}

@media (min-width: 900px) {
  .hero {
    min-height: 100svh;
    padding: calc(var(--head) + 1.4rem) 4vw 2.6rem;
    display: grid;
    grid-template-columns: minmax(16rem, 0.82fr) minmax(20rem, 1.18fr);
    grid-template-areas:
      "title title"
      "copy stage";
    column-gap: 3vw;
    row-gap: 1.1rem;
    align-items: end;
  }

  h1 {
    grid-area: title;
    width: auto;
    max-width: none;
    white-space: nowrap;
    font-size: clamp(4.8rem, 12.4cqi, 10.75rem);
    line-height: 0.8;
  }

  .hero-copy {
    grid-area: copy;
    align-self: end;
    padding-bottom: 0.4rem;
  }

  .hero-stage {
    grid-area: stage;
  }

  .arch-stack {
    height: min(64svh, 700px);
    min-height: 440px;
  }

  .room-atelier {
    min-height: 100svh;
    display: grid;
    place-items: center;
    padding: 6.5rem 4vw 4.5rem;
  }

  .oval {
    width: min(72vw, 1040px);
  }

  .room-atelier .plate {
    position: absolute;
    left: 4.5vw;
    bottom: 8vh;
    margin: 0;
  }

  .room-library {
    display: grid;
    grid-template-columns: minmax(17rem, 30rem) minmax(0, 1fr);
    align-items: center;
    gap: 0;
    min-height: 100svh;
    padding: 0 0 0 5vw;
  }

  .slash {
    height: 100svh;
    min-height: 100svh;
    margin-left: -6vw;
    clip-path: polygon(16% 0, 100% 0, 100% 100%, 0 100%);
  }

  .room-library .plate {
    position: relative;
    z-index: 2;
    margin-right: 1rem;
  }

  .room-valley {
    display: grid;
    grid-template-columns: minmax(16rem, 32rem) minmax(0, 1fr);
    align-items: center;
    min-height: 100svh;
    padding: 5rem 0 4rem 5vw;
    gap: 2vw;
  }

  .oculus {
    width: min(46vw, 680px);
    justify-self: end;
    margin: 0 -4vw 0 0;
  }

  .room-night {
    min-height: 100svh;
  }

  .night-img {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-position: 68% 46%;
  }

  .room-night .plate {
    position: absolute;
    left: 4.5vw;
    bottom: 8vh;
    margin: 0;
  }

  .ledger {
    min-height: 100svh;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(14rem, 24rem);
    align-items: center;
    gap: 4vw;
    padding: 6.5rem 5vw 4rem;
  }

  .door-wrap {
    order: 0;
    width: 100%;
    height: min(74svh, 720px);
    justify-self: end;
  }

  .colophon {
    padding-inline: 4vw;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }

  .js .plate {
    opacity: 1;
    transform: none;
  }
}

