@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes unseal {
  from {
    opacity: 0;
    transform: scaleY(0.045);
  }
  to {
    opacity: 1;
    transform: scaleY(1);
  }
}

.js .plate {
  opacity: 0;
  transform: translateY(18px) rotate(var(--tilt, 0deg));
