}

.room-library {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  padding: 1.5rem 1.15rem 3.5rem;
  overflow: hidden;
}

.slash {
  margin: 0;
  height: 52svh;
  min-height: 260px;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 86%);
  overflow: hidden;
}

.slash img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 36% 42%;
}

.room-valley {
  display: flex;
  flex-direction: column;
  gap: 1.6rem;
  padding: 1rem 1.15rem 4rem;
  overflow: hidden;
}

.oculus {
  margin: 0 auto;
  width: min(78vw, 440px);
  aspect-ratio: 1;
  border-radius: 50%;
  overflow: hidden;
