  .hero {
    min-height: 100svh;
    padding: calc(var(--head) + 1.4rem) 4vw 2.6rem;
    display: grid;
    grid-template-columns: minmax(16rem, 0.82fr) minmax(20rem, 1.18fr);
    grid-template-areas:
      "title title"
      "copy stage";
    column-gap: 3vw;
    row-gap: 1.1rem;
    align-items: end;
  }

  h1 {
