    width: 100%;
    height: min(74svh, 720px);
    justify-self: end;
  }

  .colophon {
    padding-inline: 4vw;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }

  .js .plate {
    opacity: 1;
    transform: none;
  }
}

