  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #08161c;
  --ink-2: #12303a;
  --paper: #f3ecdf;
  --coral: #ef7a66;
  --coral-ink: #7d2e28;
  --gold: #f0b429;
  --head: 3.25rem;
  --serif: "Bodoni Moda", Didot, "Bodoni MT", "Times New Roman", serif;
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  overflow-x: clip;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-weight: 400;
  font-size: 1.05rem;
  line-height: 1.5;
  text-rendering: optimizeLegibility;
}

img {
  max-width: 100%;
  display: block;
  -webkit-user-drag: none;
  user-select: none;
}

button,
input {
  font: inherit;
  color: inherit;
}

h1,
h2,
p {
  margin: 0;
}

::selection {
  background: var(--coral);
  color: var(--ink);
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.sr,
.defs {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 40;
  background: var(--paper);
  color: var(--ink);
  padding: 0.45rem 0.7rem;
  text-decoration: none;
}

.skip:focus {
  top: 0.6rem;
}

.running-head {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 20;
  height: var(--head);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0 4vw;
  background: var(--ink);
  border-bottom: 1px solid rgba(240, 180, 41, 0.42);
}

.brand {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--paper);
  text-decoration: none;
  letter-spacing: 0.01em;
}

.running-head nav {
  display: flex;
  gap: 1.2rem;
}

.running-head nav a {
  color: var(--paper);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
}

.running-head a:hover,
.running-head nav a.is-current {
  color: var(--gold);
}

.hero {
  container-type: inline-size;
  min-height: 100svh;
  padding: calc(var(--head) + 0.85rem) 1.15rem 1.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-optical-sizing: auto;
  font-size: clamp(3.15rem, 14.8vw, 4.7rem);
  line-height: 0.88;
  letter-spacing: -0.03em;
