  clip-path: url("#arch-clip");
}

.arch-gold,
.arch-layers {
  position: absolute;
  inset: 0;
}

.arch-gold {
  inset: -7px;
  background: var(--gold);
}

.arch-layers {
  background: var(--ink-2);
  overflow: hidden;
}

.composite,
.solo,
.base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.base,
.solo,
.shard img {
  object-fit: cover;
