  animation: rise 0.9s 0.16s both;
}

.dek {
  font-size: 1.2rem;
  line-height: 1.35;
}

.lede {
  margin-top: 0.4rem;
  max-width: 38ch;
  color: rgba(243, 236, 223, 0.86);
}

.hero-stage {
