}

.arch {
  cursor: ew-resize;
  touch-action: pan-y;
  --px: 0;
  --py: 0;
}

.arch-stack {
  position: relative;
  height: min(40svh, 360px);
  min-height: 230px;
  transform-origin: 50% 72%;
  animation: unseal 1.05s cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.arch-gold,
.arch-layers,
.door-gold,
.door {
  -webkit-clip-path: url("#arch-clip");
  clip-path: url("#arch-clip");
}

.arch-gold,
.arch-layers {
  position: absolute;
  inset: 0;
}

.arch-gold {
  inset: -7px;
  background: var(--gold);
}

.arch-layers {
  background: var(--ink-2);
  overflow: hidden;
}

.composite,
.solo,
.base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.base,
.solo,
.shard img {
  object-fit: cover;
}

.base {
  object-position: 50% 46%;
