  flex: 1 1 14rem;
  width: auto;
  min-width: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--gold);
  border-radius: 0;
  padding: 0.65rem 0;
  font-size: 1.05rem;
}

