const page = await browser.getPage("elysian");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));

async function measure(width, height, label) {
  await page.setViewportSize({ width, height });
  await page.goto("http://127.0.0.1:9477/", { waitUntil: "networkidle" });
  await page.waitForTimeout(500);
  const data = await page.evaluate(() => {
    const h = document.querySelector("h1").getBoundingClientRect();
    const foot = document.querySelector(".arch-foot").getBoundingClientRect();
    const arch = document.querySelector(".arch-stack").getBoundingClientRect();
    const reunite = document.querySelector(".reunite").getBoundingClientRect();
    return {
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: window.innerWidth,
      innerHeight: window.innerHeight,
      h1: { top: h.top, bottom: h.bottom, left: h.left, right: h.right, w: h.width, overflow: h.right > innerWidth - 8 },
      arch: { top: arch.top, bottom: arch.bottom, h: arch.height },
      foot: { top: foot.top, bottom: foot.bottom, visible: foot.bottom <= innerHeight + 2 && foot.top >= 0 },
      title: document.querySelector("h1").textContent,
    };
  });
  const shot = await saveScreenshot(await page.screenshot(), label + ".png");
  return { label, shot, ...data };
}

const desktop = await measure(1440, 900, "fix-desktop");
const mobile = await measure(390, 844, "fix-mobile");
const narrow = await measure(320, 700, "fix-narrow");

await page.setViewportSize({ width: 390, height: 844 });
await page.evaluate(() => window.scrollTo(0, document.getElementById("library").offsetTop - 80));
await page.waitForTimeout(300);
const lib = await saveScreenshot(await page.screenshot(), "fix-mobile-library.png");
const libOverflow = await page.evaluate(() => document.documentElement.scrollWidth);

await page.setViewportSize({ width: 1440, height: 900 });
await page.goto("http://127.0.0.1:9477/", { waitUntil: "domcontentloaded" });
await page.locator("#key-form button").click();
const invalid = await page.evaluate(() => ({
  aria: document.querySelector("#guest").getAttribute("aria-invalid"),
  error: document.querySelector("#form-error").hidden,
  text: document.querySelector("#form-error").textContent.trim(),
}));

console.log(JSON.stringify({ errors, desktop, mobile, narrow, lib, libOverflow, invalid }, null, 2));
EOF

