  background: var(--ink);
  border-bottom: 1px solid rgba(240, 180, 41, 0.42);
}

.brand {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--paper);
  text-decoration: none;
  letter-spacing: 0.01em;
}

.running-head nav {
  display: flex;
  gap: 1.2rem;
}

.running-head nav a {
  color: var(--paper);
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
}

.running-head a:hover,
.running-head nav a.is-current {
  color: var(--gold);
}

.hero {
  container-type: inline-size;
  min-height: 100svh;
  padding: calc(var(--head) + 0.85rem) 1.15rem 1.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-optical-sizing: auto;
  font-size: clamp(3.15rem, 14.8vw, 4.7rem);
