    padding: calc(var(--head) + 1.4rem) 4vw 2.6rem;
    display: grid;
    grid-template-columns: minmax(16rem, 0.82fr) minmax(20rem, 1.18fr);
    grid-template-areas:
      "title title"
      "copy stage";
    column-gap: 3vw;
    row-gap: 1.1rem;
    align-items: end;
  }

  h1 {
    grid-area: title;
    width: auto;
    max-width: none;
    white-space: nowrap;
    font-size: clamp(4.8rem, 12.4cqi, 10.75rem);
