  }

  .room-atelier .plate {
    position: absolute;
    left: 4.5vw;
    bottom: 8vh;
    margin: 0;
  }

  .room-library {
    display: grid;
    grid-template-columns: minmax(17rem, 30rem) minmax(0, 1fr);
    align-items: center;
    gap: 0;
    min-height: 100svh;
    padding: 0 0 0 5vw;
  }

  .slash {
    height: 100svh;
    min-height: 100svh;
    margin: 0 0 0 -6vw;
    clip-path: polygon(16% 0, 100% 0, 100% 100%, 0 100%);
  }

  .room-library .plate {
    position: relative;
    z-index: 2;
    margin-right: 1rem;
  }

  .room-valley {
    display: grid;
    grid-template-columns: minmax(16rem, 32rem) minmax(0, 1fr);
    align-items: center;
    min-height: 100svh;
    padding: 5rem 0 4rem 5vw;
    gap: 2vw;
  }

  .oculus {
    width: min(46vw, 680px);
    justify-self: end;
    margin: 0 -4vw 0 0;
  }

  .room-night {
    min-height: 100svh;
  }

  .night-img {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-position: 68% 46%;
  }

  .room-night .plate {
    position: absolute;
    left: 4.5vw;
    bottom: 8vh;
    margin: 0;
  }

  .ledger {
    min-height: 100svh;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(14rem, 24rem);
    align-items: center;
    gap: 4vw;
    padding: 6.5rem 5vw 4rem;
  }

  .door-wrap {
    order: 0;
    width: 100%;
    height: min(74svh, 720px);
    justify-self: end;
  }

  .colophon {
    padding-inline: 4vw;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }

  .js .plate {
    opacity: 1;
    transform: none;
  }
}

