  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #08161c;
  --ink-2: #12303a;
  --paper: #f3ecdf;
  --coral: #ef7a66;
  --coral-ink: #7d2e28;
