  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0 4vw;
  background: var(--ink);
  border-bottom: 1px solid rgba(240, 180, 41, 0.42);
}

.brand {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--paper);
  text-decoration: none;
  letter-spacing: 0.01em;
}

.running-head nav {
  display: flex;
  gap: 1.2rem;
}

.running-head nav a {
  color: var(--paper);
