dev-browser <<'EOF'
const page = await browser.getPage("elysian");

async function fit(width, height, label) {
  await page.setViewportSize({ width, height });
  await page.goto("http://127.0.0.1:9477/", { waitUntil: "networkidle" });
  await page.waitForTimeout(400);
  const data = await page.evaluate(() => {
    const foot = document.querySelector(".arch-foot").getBoundingClientRect();
    const h = document.querySelector("h1").getBoundingClientRect();
    return {
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: innerWidth,
      innerHeight: innerHeight,
      h1Right: Math.round(h.right),
      h1Overflow: h.right > innerWidth - 4,
      footBottom: Math.round(foot.bottom),
      footVisible: foot.bottom <= innerHeight + 1,
      ledeHidden: getComputedStyle(document.querySelector(".lede")).display === "none",
    };
  });
  const shot = await saveScreenshot(await page.screenshot(), label + ".png");
  return { label, shot, ...data };
}

const narrow = await fit(320, 700, "final-narrow");
const laptop = await fit(1280, 720, "final-laptop");

await page.setViewportSize({ width: 390, height: 844 });
await page.goto("http://127.0.0.1:9477/", { waitUntil: "networkidle" });
await page.locator("#library").scrollIntoViewIfNeeded();
await page.waitForTimeout(900);
const lib = await page.evaluate(() => {
  const img = document.querySelector(".slash");
  img.scrollIntoView({ block: "center" });
  const r = img.getBoundingClientRect();
  return { top: r.top, bottom: r.bottom, left: r.left, right: r.right, w: r.width };
