.arch {
  cursor: ew-resize;
  touch-action: pan-y;
  --px: 0;
  --py: 0;
}

.arch-stack {
  position: relative;
  height: min(40svh, 360px);
  min-height: 230px;
  transform-origin: 50% 72%;
  animation: unseal 1.05s cubic-bezier(0.16, 0.84, 0.28, 1) both;
}

.arch-gold,
.arch-layers,
.door-gold,
.door {
  -webkit-clip-path: url("#arch-clip");
  clip-path: url("#arch-clip");
}

.arch-gold,
.arch-layers {
  position: absolute;
  inset: 0;
}

.arch-gold {
  inset: -7px;
  background: var(--gold);
}

.arch-layers {
  background: var(--ink-2);
  overflow: hidden;
}

.composite,
.solo,
.base {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.base,
.solo,
.shard img {
  object-fit: cover;
}

.base {
  object-position: 50% 46%;
  transform: translate3d(calc(var(--px) * -12px), calc(var(--py) * -8px), 0) scale(1.06);
}

.solo {
  opacity: 0;
  object-position: 50% 45%;
  transform: translate3d(calc(var(--px) * -14px), calc(var(--py) * -10px), 0) scale(1.07);
}

.solo:nth-child(2) {
  object-position: 50% 48%;
}

.solo:nth-child(3) {
  object-position: 34% 40%;
}

.solo:nth-child(4) {
  object-position: 62% 52%;
}

.solo:nth-child(5) {
  object-position: 50% 42%;
}

.composite {
  opacity: 1;
}

.arch.is-solo .composite {
  opacity: 0;
}

.arch.is-solo .solo.is-on {
  opacity: 1;
}

.base,
.solo,
.composite,
.shard img {
  transition: opacity 0.45s ease, transform 0.4s ease-out;
}

.shard {
  position: absolute;
  overflow: hidden;
  z-index: 2;
}

.shard img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.shard-door {
  left: 7%;
