.js .plate {
  opacity: 0;
  transform: translateY(18px) rotate(var(--tilt, 0deg));
  transition: opacity 0.7s ease, transform 0.75s cubic-bezier(0.16, 0.84, 0.28, 1);
}

.js .room.is-in .plate {
  opacity: 1;
  transform: translateY(0) rotate(var(--tilt, 0deg));
}

@media (min-width: 701px) and (max-width: 899px) {
  .arch-stack {
    height: min(50svh, 520px);
    min-height: 340px;
  }
}

@media (max-width: 700px) and (max-height: 760px) {
  .hero .lede {
    display: none;
  }

  .arch-stack {
    height: min(34svh, 260px);
    min-height: 200px;
  }
}

@media (max-width: 680px) {
  :root {
    --head: 5.35rem;
  }

  .running-head {
    height: auto;
    flex-wrap: wrap;
    align-items: flex-end;
    padding: 0.7rem 1rem 0.55rem;
    row-gap: 0.35rem;
  }

  .running-head nav {
    width: 100%;
    justify-content: space-between;
    gap: 0.4rem;
  }

  .running-head nav a {

  gap: 0.75rem;
}

h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-optical-sizing: auto;
  font-size: clamp(3.15rem, 14.8vw, 4.25rem);
  line-height: 0.88;
  letter-spacing: -0.03em;
  white-space: nowrap;
  max-width: 100%;
  color: var(--paper);
  animation: rise 0.9s 0.05s both;
}

.hero-copy {
  max-width: 34rem;
  animation: rise 0.9s 0.16s both;
}
